import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"البروتوكول العام لعلم الآثار","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0084-考古协议总纲.md","filePath":"ar/0084-考古协议总纲.md"}'),h={name:"ar/0084-考古协议总纲.md"};function o(l,t,i,n,p,s){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="البروتوكول-العام-لعلم-الآثار" tabindex="-1">البروتوكول العام لعلم الآثار <a class="header-anchor" href="#البروتوكول-العام-لعلم-الآثار" aria-label="Permalink to &quot;البروتوكول العام لعلم الآثار&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>84</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>بروتوكول علم الآثار، مرآة النسخ، الفضاء المعزول، إعادة المعرفة فقط، التلوث المنخفض</td></tr></tbody></table><h2 id="أولاً-تموضع-البروتوكول-وأهدافه" tabindex="-1">أولاً: تموضع البروتوكول وأهدافه <a class="header-anchor" href="#أولاً-تموضع-البروتوكول-وأهدافه" aria-label="Permalink to &quot;أولاً: تموضع البروتوكول وأهدافه&quot;">​</a></h2><p>علم الآثار عبر الأبعاد وعلم الآثار بالارتداد الزمني وسيلتان مهمتان تكتسب بهما حضارة التكافل المرساة المعرفة التاريخية وتفهم تطور الكون. غير أن سلوك علم الآثار بحد ذاته يحمل درجة عالية من الخطر — فالدخول المباشر إلى البُعد المستهدف أو الفترة المستهدفة لإجراء حفائر أثرية قد يسبب ضرراً فيزيائياً واضطراباً في القوانين وتلوثاً ثقافياً للهدف. لضبط السلوك الأثري وتقليل الخطر الأثري، وضع كون هنغ يوان «البروتوكول العام لعلم الآثار» الموحد، ليكون المواصفة التشغيلية الجذرية لجميع الأنشطة الأثرية عبر الأبعاد وبالارتداد الزمني.</p><p>يمكن إجمال الأهداف الجوهرية للبروتوكول في «الحدود القصوى الثلاثة»: تحقيق أقصى قدر من اكتساب المعرفة التاريخية الكاملة، وتحقيق أقصى قدر من تقليل التدخل والأضرار على الهدف، وتحقيق أقصى قدر من ضمان سلامة العاملين في علم الآثار. بين هذه الأهداف الثلاثة توتر جوهري — فكمال اكتساب المعرفة يقتضي غالباً اتصالاً أعمق، بينما يحد مبدأ التدخل المنخفض من عمق الاتصال. وكل التصميم المؤسسي للبروتوكول موجه لإيجاد نقطة التوازن المثلى بينها.</p><p>يسري البروتوكول على السيناريوهات التالية: التحقيق الأثري في بقايا حضارات أبعاد مجهولة، والاستعادة التاريخية لحضارات منقرضة عبر الارتداد الزمني، وعلم الآثار العميق على مستوى القوانين للبقايا القديمة في البُعد الخاص، والحفائر الإنقاذية للآثار القديمة في أبعاد القوانين المفتتة.</p><h2 id="ثانياً-العناصر-الثلاثة-للمخطط-الأثري" tabindex="-1">ثانياً: العناصر الثلاثة للمخطط الأثري <a class="header-anchor" href="#ثانياً-العناصر-الثلاثة-للمخطط-الأثري" aria-label="Permalink to &quot;ثانياً: العناصر الثلاثة للمخطط الأثري&quot;">​</a></h2><p>يتكون المخطط الأثري القياسي في كون هنغ يوان من ثلاثة عناصر جوهرية، تعرف بـ«العناصر الثلاثة لعلم الآثار»:</p><h3 id="_2-1-مرآة-النسخ" tabindex="-1">2.1 مرآة النسخ <a class="header-anchor" href="#_2-1-مرآة-النسخ" aria-label="Permalink to &quot;2.1 مرآة النسخ&quot;">​</a></h3><p>مرآة النسخ جهاز نسخ فائق الدقة قائم على قوانين المبادئ القانونية المكانية، قادر على إجراء نسخ كامل 1:1 لبنى المادة والطاقة والمعلومات في المنطقة المستهدفة دون لمس الأصل. مبدأ عمل مرآة النسخ هو مسح جميع حالات الجسيمات وتوزيعات حقول الطاقة في المنطقة المستهدفة عبر مسح القوانين المكانية، ثم إعادة بناء نسخة مطابقة تماماً في فضاء معزول. لا تغير عملية النسخ أي حالة من حالات الأصل، وبالتالي لا تسبب أي تدخل فيزيائي في الموقع الأثري.</p><p>تبلغ دقة النسخ في مرآة النسخ المستوى دون الذري، وقادرة على إعادة بناء البنى المادية، وبقايا الطاقة، وبصمات الوعي، بل وشظايا السلاسل السببية في المنطقة المستهدفة استعادةً كاملة. يمكن ضبط نطاق النسخ وفق الاحتياج الأثري؛ فأصغر وحدة نسخ هي قطعة أثرية واحدة، وأكبرها يمكن أن يغطي مجموعة بقايا كاملة. يعتمد زمن النسخ على حجم النطاق؛ فنسخ القطعة الواحدة يكتمل عادة في دقائق، بينما قد يستغرق نسخ مجموعة بقايا كبيرة عدة أيام.</p><h3 id="_2-2-الفضاء-المعزول" tabindex="-1">2.2 الفضاء المعزول <a class="header-anchor" href="#_2-2-الفضاء-المعزول" aria-label="Permalink to &quot;2.2 الفضاء المعزول&quot;">​</a></h3><p>الفضاء المعزول منطقة قوانين مستقلة تنشأ بتقنية تسيير المبادئ القانونية المكانية، تُستخدم لاحتضان النسخ الأثرية التي تولدها مرآة النسخ، وتكون مكان عمل للعاملين في علم الآثار. يفصل الفضاء المعزول عن البُعد المستهدف أو الفترة المستهدفة حاجز قوانين كامل، يضمن ألا تنتج العمليات الأثرية أي تأثير عكسي على الأصل.</p><p>يمكن تخصيص متغيرات القوانين داخل الفضاء المعزول وفق الاحتياج الأثري، ومنها: محاكاة المتغيرات البيئية للبُعد المستهدف لضمان استقرار نسخ القطع الأثرية، ونصب حقول قوانين تحليلية خاصة لمساعدة البحث الأثري، وإنشاء حقول صارمة للوقاية من التلوث وضبطه لمنع تسرب طاقة ووعي العاملين. يمكن توسيع حجم الفضاء المعزول عند الحاجة، والحد الأقصى يتسع لنسخة بقايا على مستوى مدينة كاملة.</p><h3 id="_2-3-إعادة-المعرفة-فقط" tabindex="-1">2.3 إعادة المعرفة فقط <a class="header-anchor" href="#_2-3-إعادة-المعرفة-فقط" aria-label="Permalink to &quot;2.3 إعادة المعرفة فقط&quot;">​</a></h3><p>«إعادة المعرفة فقط» أحد المبادئ الجوهرية للبروتوكول، ومعناه ألا يُؤخذ من الهدف في العملية الأثرية سوى المعرفة والمعلومات المجردة، وألا تُعاد أي مادة أو طاقة أو كائن حي. بعد أن يدرس العاملون النسخة في الفضاء المعزول، لا يجوز لهم إحضار إلى البُعد الخاص سوى استنتاجات البحث وسجلات البيانات والتقارير التحليلية في صورة معلومات خالصة؛ أما النسخة نفسها وأي عينات مادية مستخرجة منها فيجب إتلافها داخل الفضاء المعزول.</p><p>الغرض الجوهري من هذا المبدأ منع التلوث عبر الأبعاد واضطراب الخطوط الزمنية. فحتى ذرة غبار مستخرجة من النسخة قد تحمل معلومات قوانين البُعد المستهدف؛ وبمجرد دخولها شبكة قوانين البُعد الخاص، قد تطلق تفاعلات متسلسلة غير متوقعة. لذلك، «إعادة المعرفة فقط» ليست توصية تشغيلية قابلة للتفاوض، بل مبدأ صلب ذو قوة إلزامية قانونية.</p><h2 id="ثالثاً-الإجراء-القياسي-للعمليات-الأثرية" tabindex="-1">ثالثاً: الإجراء القياسي للعمليات الأثرية <a class="header-anchor" href="#ثالثاً-الإجراء-القياسي-للعمليات-الأثرية" aria-label="Permalink to &quot;ثالثاً: الإجراء القياسي للعمليات الأثرية&quot;">​</a></h2><p>تتبع العملية الأثرية الكاملة عبر الأبعاد أو بالارتداد الزمني الإجراء القياسي التالي:</p><table tabindex="0"><thead><tr><th>المرحلة</th><th>محتوى العملية</th><th>الجهة المسؤولة</th><th>المدة المرجعية</th></tr></thead><tbody><tr><td>المرحلة الأولى: إقرار المشروع</td><td>تقديم طلب أثري، وتحديد الهدف والنطاق والمخطط، والحصول على تصريح عبور من المستوى أ أو تصريح ارتداد</td><td>الفريق الأثري ← إدارة الأبعاد / لجنة قوانين الزمن</td><td>7-30 يوماً</td></tr><tr><td>المرحلة الثانية: الملاحظة المسبقة</td><td>إجراء ملاحظة خالصة للمنطقة المستهدفة لا تقل عن 72 ساعة وفق معيار «الملاحظة أولاً ثم التدخل المحدود»</td><td>الفريق الأثري</td><td>72 ساعة فأكثر</td></tr><tr><td>المرحلة الثالثة: نشر مرآة النسخ</td><td>نشر مرآة النسخ في موقع آمن قرب المنطقة المستهدفة، وتحديد نطاق النسخ ومتغيرات الدقة</td><td>الفريق التقني</td><td>من ساعات إلى أيام</td></tr><tr><td>المرحلة الرابعة: توليد النسخة</td><td>تشغيل مرآة النسخ لنسخ المنطقة المستهدفة نسخاً كاملاً في الفضاء المعزول المجهز مسبقاً</td><td>الفريق التقني</td><td>من دقائق إلى أيام</td></tr><tr><td>المرحلة الخامسة: علم الآثار في الفضاء المعزول</td><td>دخول العاملين إلى الفضاء المعزول وإجراء حفر وتحليل وبحث منهجي على النسخة</td><td>الفريق الأثري</td><td>من أيام إلى سنوات</td></tr><tr><td>المرحلة السادسة: تنظيم المعرفة</td><td>تنظيم النتائج الأثرية، وتكوين تقارير بحثية وقواعد معارف، وضمان أن تكون جميع النتائج في صورة معلومات خالصة</td><td>الفريق الأثري</td><td>من أيام إلى أشهر</td></tr><tr><td>المرحلة السابعة: الانسحاب والإتلاف</td><td>انسحاب العاملين من الفضاء المعزول، وإتلاف جميع مواد وبقايا طاقة النسخة، وإغلاق الفضاء المعزول</td><td>الفريق التقني + فريق الرقابة</td><td>ساعات</td></tr><tr><td>المرحلة الثامنة: التدقيق اللاحق</td><td>تقديم التقرير الأثري الكامل، وقبول التدقيق اللاحق من لجنة تدقيق قوانين الزمن أو إدارة الأبعاد</td><td>لجنة التدقيق</td><td>خلال 30 يوماً</td></tr></tbody></table><h2 id="رابعاً-مؤهلات-العاملين-في-علم-الآثار-ومتطلباتهم-الأخلاقية" tabindex="-1">رابعاً: مؤهلات العاملين في علم الآثار ومتطلباتهم الأخلاقية <a class="header-anchor" href="#رابعاً-مؤهلات-العاملين-في-علم-الآثار-ومتطلباتهم-الأخلاقية" aria-label="Permalink to &quot;رابعاً: مؤهلات العاملين في علم الآثار ومتطلباتهم الأخلاقية&quot;">​</a></h2><p>يجب أن تتوفر في العاملين في علم الآثار عبر الأبعاد وبالارتداد الزمني المؤهلات التالية: زراعة تفوق المستوى الثالث من نظام تسيير المبادئ القانونية المكانية، وشهادة مؤهل من لجنة أخلاقيات علم الآثار، وإتمام تدريب أثري محاكى لا يقل عن 100 ساعة، وخلو السجل من أي انتهاك للقوانين التكافلية.</p><p>يجب على العاملين الالتزام بالمتطلبات الأخلاقية التالية: احترام ثقافة ومعتقدات الحضارة المستهدفة، والامتناع عن التمييز الثقافي أو الأحكام القيمية أثناء البحث؛ وحماية سلامة الموقع الأثري، والامتناع عن تدمير بنى البقايا من أجل الحصول على القطع الأثرية؛ وتسجيل الإبلاغ عن المكتشفات الأثرية بأمانة، والامتناع عن تزوير أو إخفاء البيانات الأثرية؛ والالتزام بمبدأ «إعادة المعرفة فقط»، والامتناع عن إخراج أي عينة مادية من الفضاء المعزول خلسة.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>البروتوكول العام لعلم الآثار هو الجسر المؤسسي الذي أقامه كون هنغ يوان بين استكشاف المعرفة وحماية الحضارات. بالعناصر الثلاثة — مرآة النسخ والفضاء المعزول وإعادة المعرفة فقط — سنداً تقنياً، وبالإجراء الموحد إطاراً تشغيلياً، وبمؤهلات العاملين ومتطلباتهم الأخلاقية ضماناً إنسانياً، يبني نموذجاً أثرياً قوامه «التلوث المنخفض، والكفاءة العالية، وقابلية التتبع». يضمن هذا النموذج أن كون هنغ يوان، في سعيه وراء الحقيقة التاريخية، يحافظ دائماً على أسمى درجات الاحترام للحضارات والعصور الأخرى.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>85-复制镜异地考古方案 (مخطط علم الآثار خارج الموقع بمرآة النسخ)</li><li>86-隔离空间低污染流程 (إجراء التلوث المنخفض للفضاءات المعزولة)</li><li>87-仅回传知识原则 (مبدأ إعادة المعرفة فقط)</li></ul>',27)])])}const b=a(h,[["render",o]]);export{c as __pageData,b as default};
